#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* ----- handle missing argument ----- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* ----- parse the argument as a decimal integer ----- */
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    /* strtol failed or did not consume the whole string */
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- range check (the original program limits to 1 000 000 000) ----- */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- numbers smaller than 2 have no prime factors ----- */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    /* ----- prime factorisation ----- */
    long remaining = n;
    int first_factor = 1;          /* true while we have not printed any factor yet */

    for (long p = 2; p * p <= remaining; ++p) {
        if (remaining % p == 0) {
            int exp = 0;
            while (remaining % p == 0) {
                remaining /= p;
                ++exp;
            }
            if (!first_factor) {
                putchar(' ');
            }
            printf("%ld^%d", p, exp);
            first_factor = 0;
        }
    }

    /* ----- if something is left, it is a prime > sqrt(original) ----- */
    if (remaining > 1) {
        if (!first_factor) {
            putchar(' ');
        }
        printf("%ld^1", remaining);
    }

    putchar('\n');
    return 0;
}
